    /// <summary>
    ///     Prime-table and fast-modulo helpers used to size the dictionary's bucket array and to reduce a
    ///     hash code to a bucket without a hardware division on 64-bit.
    /// </summary>
    /// <remarks>
    ///     Verbatim from the BCL <c>System.Collections.HashHelpers</c>, trimmed to the members the vendored
    ///     dictionary uses. <see cref="FastMod" /> and <see cref="GetFastModMultiplier" /> are only valid on
    ///     64-bit; the dictionary already branches on <see cref="IntPtr.Size" /> before calling them.
    /// </remarks>
    internal static class HashHelpers
    {
        /// <summary>The largest prime that is smaller than <see cref="Array.MaxLength" />.</summary>
        public const int MaxPrimeArrayLength = 0x7FFFFFC3;

        /// <summary>A prime whose successor gap is avoided when synthesizing capacities beyond the table.</summary>
        public const int HashPrime = 101;

        /// <summary>The increasing prime capacities the bucket array grows through before primes are computed on the fly.</summary>
        internal static ReadOnlySpan<int> Primes =>
        [
            3, 7, 11, 17, 23, 29, 37, 47, 59, 71, 89, 107, 131, 163, 197, 239, 293, 353, 431, 521, 631, 761, 919,
            1103, 1327, 1597, 1931, 2333, 2801, 3371, 4049, 4861, 5839, 7013, 8419, 10103, 12143, 14591,
            17519, 21023, 25229, 30293, 36353, 43627, 52361, 62851, 75431, 90523, 108631, 130363, 156437,
            187751, 225307, 270371, 324449, 389357, 467237, 560689, 672827, 807403, 968897, 1162687, 1395263,
            1674319, 2009191, 2411033, 2893249, 3471899, 4166287, 4999559, 5999471, 7199369
        ];

        /// <summary>Determines whether <paramref name="candidate" /> is prime.</summary>
        /// <param name="candidate">A non-negative candidate; callers only pass odd numbers or two.</param>
        /// <returns><see langword="true" /> when <paramref name="candidate" /> is prime.</returns>
        public static bool IsPrime(int candidate)
        {
            if ((candidate & 1) != 0)
            {
                int limit = (int)Math.Sqrt(candidate);
                for (int divisor = 3; divisor <= limit; divisor += 2)
                {
                    if (candidate % divisor == 0)
                    {
                        return false;
                    }
                }

                return true;
            }

            return candidate == 2;
        }

        /// <summary>Returns the smallest table prime greater than or equal to <paramref name="min" />.</summary>
        /// <param name="min">The minimum acceptable capacity.</param>
        /// <returns>A prime capacity at least <paramref name="min" />.</returns>
        /// <exception cref="ArgumentException"><paramref name="min" /> is negative (capacity overflow).</exception>
        public static int GetPrime(int min)
        {
            if (min < 0)
            {
                throw new ArgumentException(SR.Arg_HTCapacityOverflow);
            }

            foreach (int prime in Primes)
            {
                if (prime >= min)
                {
                    return prime;
                }
            }

            // Outside of our predefined table. Compute the hard way.
            for (int i = min | 1; i < int.MaxValue; i += 2)
            {
                if (IsPrime(i) && (i - 1) % HashPrime != 0)
                {
                    return i;
                }
            }

            return min;
        }

        /// <summary>Computes the reciprocal multiplier <c>ceil(2**64 / <paramref name="divisor" />)</c> for <see cref="FastMod" />.</summary>
        /// <param name="divisor">The bucket count used as the modulus; must be positive.</param>
        /// <returns>The precomputed multiplier for the divisor.</returns>
        /// <remarks>64-bit only; the dictionary computes this once per <c>Tables</c> instance.</remarks>
        public static ulong GetFastModMultiplier(uint divisor) =>
            ulong.MaxValue / divisor + 1;

        /// <summary>Reduces <paramref name="value" /> modulo <paramref name="divisor" /> using a multiply/shift instead of a division.</summary>
        /// <param name="value">The unsigned hash to reduce.</param>
        /// <param name="divisor">The bucket count; must equal the divisor passed to <see cref="GetFastModMultiplier" />.</param>
        /// <param name="multiplier">The multiplier returned by <see cref="GetFastModMultiplier" /> for <paramref name="divisor" />.</param>
        /// <returns>The remainder <c><paramref name="value" /> % <paramref name="divisor" /></c>.</returns>
        /// <remarks>64-bit only. The debug assertion cross-checks the fast path against the true remainder.</remarks>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint FastMod(uint value, uint divisor, ulong multiplier)
        {
            Debug.Assert(divisor <= int.MaxValue);
            uint highbits = (uint)(((((multiplier * value) >> 32) + 1) * divisor) >> 32);
            Debug.Assert(highbits == value % divisor);
            return highbits;
        }
    }
